import {
  ActionToolbar,
  ActionToolbarActionClear,
  ActionToolbarActions,
  ActionToolbarPrimaryAction,
  ActionToolbarSelection,
  ActionToolbarSelectionSummary,
  Button,
  Separator,
  Tabs,
  TabsList,
  TabsTrigger,
} from '@cognite/aura/components';
import { IconBuildingFactory, IconPlus } from '@tabler/icons-react';
import { type ReactNode, useState } from 'react';

import { RecordListCards } from './record-list-cards';
import { RecordListLeftPanel } from './record-list-left-panel';
import { RecordListPagination } from './record-list-pagination';
import { RecordListPreview } from './record-list-preview';
import { RecordListTable } from './record-list-table';
import {
  recordListPageDescription,
  recordListPageTitle,
  recordListPrimaryAction,
  recordListSecondaryAction,
  recordListBulkAction,
  recordListTabs,
  defaultRecordListGroupId,
  rowsForGroup,
  type RecordListLayout,
  type RecordListSampleRow,
  type RecordListView,
} from './record-list-template.data';
import { RecordListToolbar } from './record-list-toolbar';

function layoutBody(layout: RecordListLayout): 'full' | 'left' | 'right' {
  if (layout.startsWith('left-panel')) {
    return 'left';
  }
  if (layout.startsWith('right-panel')) {
    return 'right';
  }
  return 'full';
}

function PageActions(): ReactNode {
  return (
    <div className="flex shrink-0 items-center gap-2">
      <Button variant="secondary">{recordListSecondaryAction}</Button>
      <Button>
        <IconPlus size={16} stroke={1.5} />
        {recordListPrimaryAction}
      </Button>
    </div>
  );
}

function RecordListTemplate({
  layout,
}: {
  layout: RecordListLayout;
}): ReactNode {
  const body = layoutBody(layout);
  const usesTabs = layout.endsWith('tabs');
  const [tab, setTab] = useState<(typeof recordListTabs)[number]>(
    recordListTabs[0]
  );
  const [view, setView] = useState<RecordListView>('table');
  const [groupId, setGroupId] = useState(defaultRecordListGroupId);
  const [selectedIds, setSelectedIds] = useState<ReadonlySet<string>>(
    () => new Set()
  );
  const [selectedRowId, setSelectedRowId] = useState<string | null>(() =>
    layout.startsWith('right-panel')
      ? (rowsForGroup(defaultRecordListGroupId)[0]?.id ?? null)
      : null
  );

  const rows = rowsForGroup(
    body === 'left' ? groupId : defaultRecordListGroupId
  );
  const selectedRow = rows.find((row) => row.id === selectedRowId) ?? null;
  const showPreview = body === 'right' && selectedRow !== null;

  function toggleRow(id: string, checked: boolean) {
    setSelectedIds((current) => {
      const next = new Set(current);
      if (checked) {
        next.add(id);
      } else {
        next.delete(id);
      }
      return next;
    });
  }

  function toggleAll(checked: boolean) {
    setSelectedIds((current) => {
      const next = new Set(current);
      for (const row of rows) {
        if (checked) {
          next.add(row.id);
        } else {
          next.delete(row.id);
        }
      }
      return next;
    });
  }

  function selectRow(row: RecordListSampleRow) {
    setSelectedRowId((current) => (current === row.id ? null : row.id));
  }

  return (
    <div
      id="record-list"
      data-slot="record-list-template"
      className="relative flex h-[52rem] w-full min-w-0 flex-col overflow-hidden rounded-xl border bg-background"
    >
      <div className="flex min-h-0 flex-1">
        {body === 'left' ? (
          <RecordListLeftPanel
            selectedGroupId={groupId}
            onSelectGroup={setGroupId}
          />
        ) : null}
        <div className="flex min-h-0 min-w-0 flex-1 flex-col gap-4 p-6">
          {usesTabs ? (
            <div className="flex flex-wrap items-center justify-between gap-3">
              <Tabs
                value={tab}
                onValueChange={(value) => {
                  const next = recordListTabs.find((item) => item === value);
                  if (next) {
                    setTab(next);
                  }
                }}
              >
                <TabsList>
                  {recordListTabs.map((item) => (
                    <TabsTrigger key={item} value={item}>
                      {item}
                    </TabsTrigger>
                  ))}
                </TabsList>
              </Tabs>
            </div>
          ) : (
            <div className="flex flex-wrap items-center justify-between gap-3">
              <div className="flex min-w-0 items-center gap-3">
                <span className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-muted-background text-muted-foreground">
                  <IconBuildingFactory size={18} stroke={1.5} />
                </span>
                <div className="min-w-0">
                  <h2 className="text-base font-medium leading-5">
                    {recordListPageTitle}
                  </h2>
                  <p className="text-sm text-muted-foreground">
                    {recordListPageDescription}
                  </p>
                </div>
              </div>
              <PageActions />
            </div>
          )}
          <Separator />
          <RecordListToolbar view={view} onViewChange={setView} />
          <div className="flex min-h-0 min-w-0 flex-1 flex-col gap-3">
            {view === 'cards' ? (
              <RecordListCards rows={rows} />
            ) : (
              <RecordListTable
                rows={rows}
                selectedIds={selectedIds}
                selectedRowId={selectedRow?.id ?? null}
                showCheckboxes={body !== 'right'}
                onToggleRow={toggleRow}
                onToggleAll={toggleAll}
                onRowClick={body === 'right' ? selectRow : undefined}
                onClearSelection={
                  body === 'right' ? () => setSelectedRowId(null) : undefined
                }
              />
            )}
            <RecordListPagination />
          </div>
        </div>
        {showPreview ? <RecordListPreview row={selectedRow} /> : null}
      </div>
      {body === 'right' ? null : (
        <div className="pointer-events-none absolute inset-x-0 bottom-10 z-10 flex justify-center overflow-hidden">
          <ActionToolbar
            selectedCount={selectedIds.size}
            className="pointer-events-auto"
          >
            <ActionToolbarSelection>
              <ActionToolbarSelectionSummary />
              <ActionToolbarActionClear
                onClick={() => {
                  setSelectedIds(new Set());
                }}
              />
            </ActionToolbarSelection>
            <ActionToolbarActions>
              <ActionToolbarPrimaryAction>
                {recordListBulkAction}
              </ActionToolbarPrimaryAction>
            </ActionToolbarActions>
          </ActionToolbar>
        </div>
      )}
    </div>
  );
}

RecordListTemplate.displayName = 'RecordListTemplate';

export { RecordListTemplate };

import {
  Card,
  CardContent,
  CardHeader,
  CardHeaderCenter,
  CardHeaderEnd,
  CardTitle,
} from '@cognite/aura/components';
import { cn } from '@cognite/aura/utils';
import type { ReactNode } from 'react';

import {
  formatRecordListReading,
  type RecordListSampleRow,
  type RecordListStatus,
} from './record-list-template.data';
import { RecordListTrend, recordListTrendColor } from './record-list-trend';

const recordListTitleClass =
  'font-sans text-base font-medium leading-5 tracking-normal min-h-10';

const statusTone: Record<
  RecordListStatus,
  { text: string; dot: string; chip: string; chart: string }
> = {
  Running: {
    text: 'text-success-foreground',
    dot: 'bg-success-foreground',
    chip: 'bg-success-muted-background text-success-foreground',
    chart: recordListTrendColor('Running'),
  },
  Standby: {
    text: 'text-muted-foreground',
    dot: 'bg-muted-foreground',
    chip: 'bg-muted-background text-foreground',
    chart: recordListTrendColor('Standby'),
  },
  Alarm: {
    text: 'text-destructive-foreground',
    dot: 'bg-destructive-foreground',
    chip: 'bg-destructive-muted-background text-destructive-foreground',
    chart: recordListTrendColor('Alarm'),
  },
  Maintenance: {
    text: 'text-warning-foreground',
    dot: 'bg-warning-foreground',
    chip: 'bg-warning-muted-background text-warning-foreground',
    chart: recordListTrendColor('Maintenance'),
  },
  Offline: {
    text: 'text-muted-foreground',
    dot: 'bg-muted-foreground',
    chip: 'bg-muted-background text-foreground',
    chart: recordListTrendColor('Offline'),
  },
  Starting: {
    text: 'text-info-foreground',
    dot: 'bg-info-foreground',
    chip: 'bg-info-muted-background text-info-foreground',
    chart: recordListTrendColor('Starting'),
  },
};

function RecordListCards({ rows }: { rows: RecordListSampleRow[] }): ReactNode {
  return (
    <ul
      data-slot="record-list-cards"
      aria-label="Assets"
      className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-3"
    >
      {rows.map((row) => {
        const tone = statusTone[row.status];
        return (
          <li key={row.id} className="flex">
            <Card className="h-full w-full">
              <CardHeader>
                <CardHeaderCenter>
                  <CardTitle className={recordListTitleClass}>
                    {row.signal} on {row.code}
                  </CardTitle>
                  <p
                    className={cn(
                      'flex items-center gap-1.5 text-sm font-medium leading-5',
                      tone.text
                    )}
                  >
                    <span
                      className={cn('size-2 shrink-0 rounded-full', tone.dot)}
                      aria-hidden="true"
                    />
                    {row.status}
                  </p>
                </CardHeaderCenter>
                <CardHeaderEnd>
                  <div
                    className={cn(
                      'flex flex-col items-center rounded-lg px-2 py-1',
                      tone.chip
                    )}
                  >
                    <span className="text-sm font-medium leading-5">
                      {formatRecordListReading(row.trend)}
                    </span>
                    <span className="text-xs leading-4">{row.unit}</span>
                  </div>
                </CardHeaderEnd>
              </CardHeader>
              <CardContent>
                <RecordListTrend
                  label={`${row.signal} on ${row.code}`}
                  values={row.trend}
                  color={tone.chart}
                />
              </CardContent>
            </Card>
          </li>
        );
      })}
    </ul>
  );
}

RecordListCards.displayName = 'RecordListCards';

export { RecordListCards };

import { Search } from '@cognite/aura/components';
import { cn } from '@cognite/aura/utils';
import type { ReactNode } from 'react';

import { recordListGroups } from './record-list-template.data';

function RecordListLeftPanel({
  selectedGroupId,
  onSelectGroup,
}: {
  selectedGroupId: string;
  onSelectGroup: (groupId: string) => void;
}): ReactNode {
  return (
    <aside
      data-slot="record-list-left-panel"
      aria-label="Equipment"
      className="flex w-64 shrink-0 flex-col gap-3 border-r p-4"
    >
      <Search aria-label="Search areas" placeholder="Search areas" />
      <div className="flex flex-col gap-4">
        {recordListGroups.map((group) => (
          <section key={group.id} className="flex flex-col gap-1">
            <h3 className="px-2 text-sm font-medium">{group.label}</h3>
            <ul className="flex flex-col">
              {group.items.map((item) => {
                const selected = item.id === selectedGroupId;
                return (
                  <li key={item.id}>
                    <button
                      type="button"
                      aria-pressed={selected}
                      className={cn(
                        'w-full rounded-md px-2 py-1.5 text-left text-sm',
                        selected
                          ? 'bg-muted-background font-medium'
                          : 'hover:bg-muted-background'
                      )}
                      onClick={() => onSelectGroup(item.id)}
                    >
                      {item.label}
                    </button>
                  </li>
                );
              })}
            </ul>
          </section>
        ))}
      </div>
    </aside>
  );
}

RecordListLeftPanel.displayName = 'RecordListLeftPanel';

export { RecordListLeftPanel };

import {
  Badge,
  Button,
  CardContent,
  CardDescription,
  CardTitle,
} from '@cognite/aura/components';
import type { ReactNode } from 'react';

import {
  formatRecordListDate,
  recordListStatuses,
  type RecordListSampleRow,
} from './record-list-template.data';
import { RecordListTrend, recordListTrendColor } from './record-list-trend';

function RecordListPreview({ row }: { row: RecordListSampleRow }): ReactNode {
  return (
    <aside
      data-slot="record-list-preview"
      aria-label="Preview"
      className="flex w-80 shrink-0 flex-col border-l p-4"
    >
      <CardTitle className="font-sans text-base font-medium leading-5 tracking-normal">
        {row.asset}
      </CardTitle>
      <CardDescription>{row.area}</CardDescription>
      <div className="flex min-h-0 flex-1 flex-col">
        <CardContent>
          <Badge variant={recordListStatuses[row.status]}>{row.status}</Badge>
          <span>{row.summary}</span>
          <span>
            Owner {row.owner}. Updated {formatRecordListDate(row.updated)}.
          </span>
        </CardContent>
        <RecordListTrend
          label={`${row.signal} on ${row.code}`}
          values={row.trend}
          color={recordListTrendColor(row.status)}
        />
      </div>
      <div className="flex gap-2">
        <Button variant="secondary" className="flex-1">
          Add comment
        </Button>
        <Button className="flex-1">Open asset</Button>
      </div>
    </aside>
  );
}

RecordListPreview.displayName = 'RecordListPreview';

export { RecordListPreview };

import {
  Avatar,
  AvatarFallback,
  Badge,
  Button,
  CheckboxItem,
  CheckboxItemControl,
  CheckboxItemLabel,
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@cognite/aura/components';
import { DataGrid } from '@cognite/aura/data-grid';
import { IconDotsVertical } from '@tabler/icons-react';
import type { ColumnDef } from '@tanstack/react-table';
import { type ReactNode, useMemo } from 'react';

import {
  formatRecordListDate,
  recordListOwners,
  recordListStatuses,
  type RecordListSampleRow,
} from './record-list-template.data';
import { RecordListTrend, recordListTrendColor } from './record-list-trend';

function RecordListTable({
  rows,
  selectedIds,
  selectedRowId,
  showCheckboxes,
  onToggleRow,
  onToggleAll,
  onRowClick,
  onClearSelection,
}: {
  rows: RecordListSampleRow[];
  selectedIds: ReadonlySet<string>;
  selectedRowId: string | null;
  showCheckboxes: boolean;
  onToggleRow: (id: string, checked: boolean) => void;
  onToggleAll: (checked: boolean) => void;
  onRowClick?: (row: RecordListSampleRow) => void;
  onClearSelection?: () => void;
}): ReactNode {
  const allSelected =
    rows.length > 0 && rows.every((row) => selectedIds.has(row.id));
  const someSelected =
    rows.some((row) => selectedIds.has(row.id)) && !allSelected;

  const columns = useMemo<ColumnDef<RecordListSampleRow>[]>(() => {
    const selectColumn: ColumnDef<RecordListSampleRow> = {
      id: 'select',
      size: 48,
      header: () => (
        <CheckboxItem>
          <CheckboxItemControl
            checked={allSelected}
            indeterminate={someSelected}
            onCheckedChange={(checked) => onToggleAll(checked === true)}
          />
          <CheckboxItemLabel className="sr-only">
            Select all rows
          </CheckboxItemLabel>
        </CheckboxItem>
      ),
      cell: ({ row }) => (
        <CheckboxItem>
          <CheckboxItemControl
            checked={selectedIds.has(row.original.id)}
            onCheckedChange={(checked) =>
              onToggleRow(row.original.id, checked === true)
            }
          />
          <CheckboxItemLabel className="sr-only">
            Select row {row.original.index}
          </CheckboxItemLabel>
        </CheckboxItem>
      ),
    };

    return [
      ...(showCheckboxes ? [selectColumn] : []),
      {
        accessorKey: 'asset',
        header: 'Asset',
        size: 280,
        cell: ({ row, getValue }) => {
          const value = String(getValue() ?? '');
          if (row.original.id !== selectedRowId) {
            return value;
          }
          return (
            <span className="whitespace-nowrap bg-muted-background">
              {value}
            </span>
          );
        },
      },
      {
        accessorKey: 'status',
        header: 'Status',
        size: 148,
        cell: ({ row }) => (
          <Badge variant={recordListStatuses[row.original.status]}>
            {row.original.status}
          </Badge>
        ),
      },
      {
        accessorKey: 'owner',
        header: 'Owner',
        size: 196,
        cell: ({ row }) => {
          const owner = recordListOwners[row.original.owner];
          return (
            <span className="flex items-center gap-2 whitespace-nowrap">
              <Avatar sizes="xsm" variant={owner.variant}>
                <AvatarFallback>{owner.initials}</AvatarFallback>
              </Avatar>
              {row.original.owner}
            </span>
          );
        },
      },
      {
        accessorKey: 'trend',
        header: 'Pressure',
        size: 148,
        cell: ({ row }) => (
          <RecordListTrend
            compact
            label={`${row.original.asset} pressure`}
            values={row.original.trend}
            color={recordListTrendColor(row.original.status)}
          />
        ),
      },
      {
        accessorKey: 'updated',
        header: 'Updated',
        size: 140,
        cell: ({ getValue }) => formatRecordListDate(String(getValue() ?? '')),
      },
      {
        id: 'actions',
        size: 48,
        header: () => <span className="sr-only">Actions</span>,
        cell: ({ row }) => (
          <DropdownMenu>
            <DropdownMenuTrigger
              render={<Button variant="ghost" size="icon-sm" />}
              aria-label={`Actions for ${row.original.asset}`}
            >
              <IconDotsVertical size={16} stroke={1.5} />
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuItem>Open asset</DropdownMenuItem>
              <DropdownMenuItem>Add comment</DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        ),
      },
    ];
  }, [
    allSelected,
    onToggleAll,
    onToggleRow,
    selectedIds,
    selectedRowId,
    showCheckboxes,
    someSelected,
  ]);

  return (
    <div
      data-slot="record-list-table"
      className="min-h-0 flex-1"
      onClick={(event) => {
        if (!onClearSelection) {
          return;
        }
        const target = event.target;
        if (!(target instanceof Element)) {
          return;
        }
        if (target.closest('[role="row"]')) {
          return;
        }
        onClearSelection();
      }}
    >
      <DataGrid
        aria-label="Record list"
        className="h-full"
        data={rows}
        columns={columns}
        getRowId={(row) => row.id}
        onRowClick={
          onRowClick
            ? (row) => {
                onRowClick(row.original);
              }
            : undefined
        }
      />
    </div>
  );
}

RecordListTable.displayName = 'RecordListTable';

export { RecordListTable };

export const recordListLayouts = [
  { id: 'full-width-header', name: 'Full width data grid + header' },
  { id: 'full-width-tabs', name: 'Full width data grid + tabs' },
  { id: 'left-panel-header', name: 'Left panel + data grid + header' },
  { id: 'left-panel-tabs', name: 'Left panel + data grid + tabs' },
  { id: 'right-panel-header', name: 'Data grid + right panel + header' },
  { id: 'right-panel-tabs', name: 'Data grid + right panel + tabs' },
] as const;

export type RecordListLayout = (typeof recordListLayouts)[number]['id'];

export type RecordListView = 'table' | 'cards';

export const recordListLayoutNames = recordListLayouts.map(
  (layout) => layout.name
);

export const recordListPageTitle = 'Plant assets';

export const recordListPageDescription =
  'Rotating and static equipment across the refinery';

export const recordListPrimaryAction = 'Create work order';

export const recordListSecondaryAction = 'Export';

export const recordListBulkAction = 'Assign crew';

export const recordListTabs = [
  'Operations',
