  'Erik Nilsen': { initials: 'EN', variant: 'decorative-4' },
  'Amira Hassan': { initials: 'AH', variant: 'decorative-5' },
  'Luis Ortega': { initials: 'LO', variant: 'decorative-6' },
  'Sofia Alvarez': { initials: 'SA', variant: 'decorative-7' },
